<style>
.seller-product-form{max-width:768px;margin:0 auto;color:#34483f;font-size:14px;line-height:1.5}
.seller-product-form *{box-sizing:border-box}.seller-product-form h2{font-size:24px;font-weight:600;letter-spacing:-.5px;color:#173f35;margin:0}
.seller-product-form h3{font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:1px;color:#1f6f5b;margin:0 0 16px}
.seller-product-form p{font-size:12px;color:#728078;margin:6px 0 12px}.seller-product-form a{color:#1f6f5b;font-weight:600;font-size:13px}
.seller-product-form .spf-intro{display:flex;gap:16px;align-items:center;justify-content:space-between;margin-bottom:24px}.seller-product-form nav{font-size:11px;margin-bottom:8px}
.seller-product-form .spf-card{border:1px solid #dde6e1;border-radius:16px;padding:22px;background:white;margin-bottom:20px;box-shadow:0 1px 3px #173f3508}
.seller-product-form label{display:block;font-size:13px;font-weight:600;margin:0 0 7px}.seller-product-form input,.seller-product-form select,.seller-product-form textarea{display:block;width:100%;border:1px solid #dde6e1;border-radius:12px;background:#fff;padding:11px 13px;color:#34483f;font-size:14px;min-width:0;outline:none;font-weight:400}
.seller-product-form input:focus,.seller-product-form select:focus,.seller-product-form textarea:focus{border-color:#1f6f5b;box-shadow:0 0 0 3px #ddf3ec}.seller-product-form input[readonly]{background:#f5f8f6;color:#728078;font-size:12px}
.seller-product-form [aria-invalid=true]{border-color:#d64c4c}.seller-product-form .spf-error{color:#b42318;min-height:0}.seller-product-form .spf-error:empty{margin-bottom:12px}
.seller-product-form .spf-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px 18px}.seller-product-form .spf-option-row{display:grid;grid-template-columns:1fr 1fr auto;gap:10px;align-items:end;margin-bottom:12px}
.seller-product-form button{border:1px solid #dde6e1;border-radius:10px;padding:9px 13px;font-size:12px;font-weight:600;color:#52635b;background:white;cursor:pointer}.seller-product-form button:hover{background:#eef5f1}.seller-product-form button:focus-visible,.seller-product-form a:focus-visible{outline:2px solid #1f6f5b;outline-offset:3px}
.seller-product-form .spf-option-row button{margin-bottom:7px}.seller-product-form .spf-variant-heading{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:24px 0 12px}.seller-product-form .spf-variant-heading button{border-color:#1f6f5b;color:#1f6f5b;background:#f7fbf9}.seller-product-form .spf-variant-heading button:hover{background:#e7f3ee}.seller-product-form .spf-variant-chip-panel{border:1px solid #dde6e1;border-radius:14px;background:#f8fbf9;padding:14px 16px;margin-bottom:14px}.seller-product-form .spf-variant-chip-group{display:grid;grid-template-columns:70px 1fr;gap:10px;align-items:start}.seller-product-form .spf-variant-chip-group+.spf-variant-chip-group{margin-top:12px}.seller-product-form .spf-variant-chip-label{font-size:12px;font-weight:700;color:#52635b;padding-top:5px}.seller-product-form .spf-variant-chips{display:flex;flex-wrap:wrap;gap:7px}.seller-product-form .spf-variant-chip{display:inline-flex;align-items:center;gap:5px;border:1px solid #bfd2c8;border-radius:999px;background:white;padding:5px 9px;font-size:12px;font-weight:600;color:#1f6f5b;line-height:1}.seller-product-form .spf-variant-empty{font-size:12px;color:#8a9891;padding:5px 0}.seller-product-form .spf-variant-list{display:grid;gap:12px}.seller-product-form .product-variant-row{border:1px solid #dde6e1;border-radius:14px;padding:16px;margin:0;background:#fff;box-shadow:0 1px 2px #173f3508}.seller-product-form .product-variant-row:hover{border-color:#c9d8d1}.seller-product-form output{display:block;font-size:12px;font-weight:600;margin:6px 0;color:#1f6f5b}.seller-product-form output[data-level=low],.seller-product-form output[data-level=empty]{color:#b54708}
.seller-product-form .spf-photos{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:12px 0}.seller-product-form figure{margin:0;min-width:0}.seller-product-form figure img{width:100%;height:135px;object-fit:contain;border:1px solid #dde6e1;border-radius:12px;background:#f5f8f6}.seller-product-form figcaption{font-size:12px;overflow-wrap:anywhere;margin-top:5px}.seller-product-form figure label{font-size:11px;margin-top:5px}
.seller-product-form .spf-upload{border:2px dashed #c8d6cf;border-radius:14px;padding:20px;text-align:center;background:#f5f8f6;color:#173f35}.seller-product-form input[type=file]{font-size:12px;margin-top:12px;background:white;padding:8px}
.seller-product-form summary{cursor:pointer;font-size:13px;font-weight:600}.seller-product-form details[open] summary{margin-bottom:16px}.seller-product-form .spf-primary{background:#1f6f5b;color:white;width:100%;font-size:14px;padding:12px;margin:8px 0 14px}.seller-product-form .spf-primary:hover{background:#173f35}.seller-product-form button:disabled{opacity:.5;cursor:not-allowed}.seller-product-form .spf-actions{text-align:center}.seller-product-form .spf-errors{border:1px solid #f5bcbc;background:#fff5f5;color:#b42318;padding:16px;border-radius:12px;margin-bottom:20px}.seller-product-form .spf-errors ul{padding-left:20px;list-style:disc}
@media(max-width:600px){.seller-product-form .spf-card{padding:16px}.seller-product-form .spf-grid{grid-template-columns:1fr}.seller-product-form .spf-intro{align-items:start;flex-direction:column;gap:4px}.seller-product-form .spf-option-row{grid-template-columns:1fr 1fr}.seller-product-form .spf-option-row button{grid-column:1/-1;justify-self:start}.seller-product-form .spf-photos{grid-template-columns:repeat(2,minmax(0,1fr))}.seller-product-form .spf-variant-heading{align-items:start;flex-direction:column}.seller-product-form .spf-variant-chip-group{grid-template-columns:1fr;gap:4px}}
</style>
